func newBriefing() unsafe.Pointer { return unsafe.Pointer(new(briefing.Briefing)) }

func newNBriefing(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]briefing.Briefing, n)))
}

func ptrBriefing(p unsafe.Pointer, c int32) any {
	r := (*briefing.Briefing)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RoleKey))
	case 4:
		return (**string)(unsafe.Pointer(&r.UserID))
	case 5:
		return &r.BriefingDate
	case 6:
		return (*string)(unsafe.Pointer(&r.RunID))
	case 7:
		return (*string)(unsafe.Pointer(&r.Status))
	case 8:
		return &r.Headline
	case 9:
		return &r.HeadlineLinks
	case 10:
		return &r.Sections
	case 11:
		return &r.Facts
	case 12:
		return &r.Narrated
	case 13:
		return &r.ModelIdentifier
	case 14:
		return (*string)(unsafe.Pointer(&r.ProviderID))
	case 15:
		return &r.FailureReason
	case 16:
		return &r.EmailedAt
	case 17:
		return &r.ReadAt
	case 18:
		return &r.Version
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueBriefing(p unsafe.Pointer, c int32) any {
	r := (*briefing.Briefing)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RoleKey)
	case 4:
		if r.UserID == nil {
			return nil
		}
		return string(*r.UserID)
	case 5:
		return r.BriefingDate
	case 6:
		if r.RunID == "" {
			return nil
		}
		return string(r.RunID)
	case 7:
		return string(r.Status)
	case 8:
		if r.Headline == "" {
			return nil
		}
		return r.Headline
	case 9:
		if r.HeadlineLinks == nil {
			return keel.EmptyJSONArray
		}
		return r.HeadlineLinks
	case 10:
		if r.Sections == nil {
			return keel.EmptyJSONArray
		}
		return r.Sections
	case 11:
		if r.Facts == nil {
			return keel.EmptyJSONObject
		}
		return r.Facts
	case 12:
		return r.Narrated
	case 13:
		if r.ModelIdentifier == "" {
			return nil
		}
		return r.ModelIdentifier
	case 14:
		if r.ProviderID == "" {
			return nil
		}
		return string(r.ProviderID)
	case 15:
		if r.FailureReason == "" {
			return nil
		}
		return r.FailureReason
	case 16:
		if r.EmailedAt == nil {
			return nil
		}
		return *r.EmailedAt
	case 17:
		if r.ReadAt == nil {
			return nil
		}
		return *r.ReadAt
	case 18:
		return r.Version
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

